package com.game_manager.gm.document;
import com.game_manager.gm.common.config.GManagerProperties; import com.game_manager.gm.document.storage.*; import java.nio.file.*; import java.sql.Timestamp; import java.time.Clock; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @ConditionalOnProperty(prefix="app.jobs",name="enabled",havingValue="true") public class LegacyMediaMigrationWorker {private final JdbcTemplate db;private final DocumentStorage storage;private final DocumentScanner scanner;private final Path root;private final Clock clock;public LegacyMediaMigrationWorker(JdbcTemplate db,DocumentStorage storage,DocumentScanner scanner,GManagerProperties p,Clock clock){this.db=db;this.storage=storage;this.scanner=scanner;root=p.storage().localRoot().toAbsolutePath().normalize();this.clock=clock;}@Scheduled(initialDelayString="${app.documents.legacy-migration-initial-delay-millis:10000}",fixedDelayString="${app.documents.legacy-migration-interval-millis:86400000}")@Transactional public void migrateDiscovered(){for(Map<String,Object> row:db.queryForList("SELECT id,legacy_url FROM legacy_media_inventory WHERE status='DISCOVERED'"))migrate(String.valueOf(row.get("id")),String.valueOf(row.get("legacy_url")));}
 private void migrate(String inventoryId,String url){try{if(!url.startsWith("/media/"))throw new IllegalArgumentException();Path source=root.resolve(url.substring(7)).normalize();if(!source.startsWith(root)||!Files.isRegularFile(source))throw new IllegalStateException();byte[] bytes=Files.readAllBytes(source);String mime=Files.probeContentType(source);if(!scanner.scan(new java.io.ByteArrayInputStream(bytes),mime).clean())throw new IllegalStateException();UUID documentId=UUID.randomUUID(),versionId=UUID.randomUUID();String resourceType=url.contains("/avatars/")?"USER_AVATAR":"CATALOG_IMAGE",resourceId=resource(url),owner=resourceType.equals("USER_AVATAR")?resourceId:owner();String key="legacy/"+documentId+"/"+versionId;StoredObject stored=storage.store(key,new java.io.ByteArrayInputStream(bytes),bytes.length);Timestamp now=Timestamp.from(clock.instant());db.update("INSERT INTO documents(id,owner_id,resource_type,resource_id,display_name,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,0)",documentId.toString(),owner,resourceType,resourceId,source.getFileName().toString(),now,now);db.update("INSERT INTO document_versions(id,document_id,version_number,object_key,original_filename,content_type,size_bytes,checksum_sha256,scan_status,scan_detail,scanned_at,created_by,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)",versionId.toString(),documentId.toString(),1,key,source.getFileName().toString(),mime,bytes.length,stored.checksumSha256(),"CLEAN","Legacy file verified",now,owner,now,now);String secure="/api/v1/documents/"+documentId+"/content?preview=true";if(resourceType.equals("USER_AVATAR"))db.update("UPDATE users SET avatar_url=? WHERE id=? AND avatar_url=?",secure,resourceId,url);else db.update("UPDATE catalog_items SET image_url=? WHERE id=? AND image_url=?",secure,resourceId,url);db.update("UPDATE legacy_media_inventory SET document_id=?,source_checksum_sha256=?,migrated_checksum_sha256=?,status='VERIFIED',checked_at=? WHERE id=?",documentId.toString(),stored.checksumSha256(),stored.checksumSha256(),now,inventoryId);}catch(Exception e){db.update("UPDATE legacy_media_inventory SET status='FAILED',checked_at=? WHERE id=?",Timestamp.from(clock.instant()),inventoryId);}}
 private String resource(String url){List<String> ids=db.query("SELECT id FROM users WHERE avatar_url=? UNION ALL SELECT id FROM catalog_items WHERE image_url=?",(r,n)->r.getString(1),url,url);if(ids.isEmpty())throw new IllegalStateException();return ids.getFirst();}private String owner(){List<String> ids=db.query("SELECT id FROM users WHERE role='OWNER' AND deleted_at IS NULL ORDER BY created_at LIMIT 1",(r,n)->r.getString(1));if(ids.isEmpty())throw new IllegalStateException();return ids.getFirst();}}
